function WaterfallGiftManager:onActInfoUpdate(event)
    local data = event:getData()

    if data and data.fromServer then
        local actInfo = data.actInfos[tostring(ACT_ID)]

        local actInfoValid = false
        if actInfo and actInfo.extra then
            local extra = table.deserialize(actInfo.extra)
            if extra and extra.subInfos then
                for _, v in pairs(extra.subInfos) do
                    if v.module == "waterfall2025" then
                        dataModel:syncFromActInfo(v)
                        actInfoValid = true
                        break
                    end
                end
            end
        end

        if actInfoValid then
            self:registerGiftModule()
        else
            dataModel:clearAct()
        end
        self:updateIcon()
    end
end

