function WaterfallGiftManager:_cancelIconV2BoundaryTimer()
    local timerId = self._iconV2BoundaryTimerId
    local timerSource = self._iconV2BoundaryTimerSource
    self._iconV2BoundaryTimerId = nil
    self._iconV2BoundaryTimerSource = nil
    if not timerId then
        return
    end
    if timerSource == "timer_util" and TimerUtil and type(TimerUtil.removeAlarm) == "function" then
        pcall(TimerUtil.removeAlarm, timerId)
    elseif type(cancelTimeOut) == "function" then
        pcall(cancelTimeOut, timerId)
    end
end

function WaterfallGiftManager:_scheduleIconV2Boundary()
    self:_cancelIconV2BoundaryTimer()
    if not self:isV2IconActive() then
        return true
    end

    local now = TimeKit and type(TimeKit.timeInSec) == "function" and tonumber(TimeKit:timeInSec()) or nil
    local endTime = tonumber(self:getEndTime())
    if not now or not endTime then
        return false, "WATERFALL_GIFT_ICON_V2_BOUNDARY_TIME_REQUIRED"
    end
    if endTime <= now then
        return self:onDeprecated()
    end

    local delay = math.max(1, math.floor(endTime - now) + 1)
    local timerId
    local timerSource
    local function onBoundary()
        if self._iconV2BoundaryTimerId ~= timerId then
            return
        end
        self._iconV2BoundaryTimerId = nil
        self._iconV2BoundaryTimerSource = nil
        self:updateIcon()
    end
    if type(setTimeOut) == "function" then
        local ok, result = pcall(setTimeOut, onBoundary, delay)
        if ok and result ~= nil then
            timerId = result
            timerSource = "timeout"
        end
    end
    if not timerId and TimerUtil and type(TimerUtil.addOnce) == "function" then
        local ok, result = pcall(TimerUtil.addOnce, onBoundary, delay)
        if ok and result ~= nil then
            timerId = result
            timerSource = "timer_util"
        end
    end
    if not timerId then
        return false, "WATERFALL_GIFT_ICON_V2_BOUNDARY_TIMER_REQUIRED"
    end
    self._iconV2BoundaryTimerId = timerId
    self._iconV2BoundaryTimerSource = timerSource
    return true
end

