function WaterfallGiftManager:createPackageIconAdapter()
    local adapterLoaded, PackageIconV2Adapter = pcall(require, PACKAGE_ICON_V2_ADAPTER_MODULE)
    if not adapterLoaded or type(PackageIconV2Adapter.create) ~= "function" then
        return nil, PackageIconV2Adapter, nil, nil, true
    end

    local configOk, options, provider = pcall(function()
        local IconV2Config = require "amf.feature.localactivity.waterfallgift.icon.IconV2Config"
        return IconV2Config.create(self, IconEventCenter)
    end)
    if not configOk then
        return nil, options, nil, nil, true
    end

    local createOk, adapter, modeOrError, cleanupOwner = pcall(
        PackageIconV2Adapter.create,
        PackageIconV2Adapter,
        options
    )
    if not createOk then
        return nil, adapter, nil, nil, false
    end
    if not adapter then
        return nil, modeOrError, cleanupOwner, nil, false
    end
    return adapter, nil, nil, modeOrError == "v2" and provider or nil, false
end

function WaterfallGiftManager:_disposeIconAdapter()
    local adapter = self.iconAdapter
    if not adapter then
        return true
    end
    local ok, disposed, disposeError = pcall(adapter.dispose, adapter)
    if not ok or disposed == false then
        logIconV2Error("dispose failed: " .. tostring(ok and disposeError or disposed))
        return false, ok and disposeError or disposed
    end
    self.iconAdapter = nil
    self.iconDataProvider = nil
    self._iconAdapterCleanupPending = false
    self.icon = nil
    return true
end

function WaterfallGiftManager:_refreshOwnedIcon(reason, payload)
    if not self.iconAdapter then
        IconEventCenter:refreshIconEvent(IconKey.kWaterfallGift)
        return true
    end
    if not self:isV2IconActive() then
        IconEventCenter:refreshIconEvent(IconKey.kWaterfallGift)
        return true
    end
    local ok, refreshed, refreshError = pcall(
        self.iconAdapter.refresh,
        self.iconAdapter,
        reason or "waterfall_gift_update",
        payload
    )
    if not ok or refreshed == false then
        logIconV2Error("refresh failed: " .. tostring(ok and refreshError or refreshed))
        return false, ok and refreshError or refreshed
    end
    local scheduled, scheduleError = self:_scheduleIconV2Boundary()
    if scheduled == false then
        logIconV2Error("schedule boundary failed: " .. tostring(scheduleError))
    end
    return true
end

function WaterfallGiftManager:_addLegacyIconIfNotExist()
    IconEventCenter:addIconIfNotExist(IconKey.kWaterfallGift, function()
