function WaterfallGiftManager:doCreateIconAsync()
    local useV2 = self:isV2IconExperimentEnabled()
    local res_map
    if useV2 then
        local IconV2Config = require "amf.feature.localactivity.waterfallgift.icon.IconV2Config"
        res_map = IconV2Config.getPreloadFiles()
    else
        res_map = self:getIconResMap()
    end
    AssetsUtil:loadMiniFiles(res_map):next(function()
        if not self:isEnabled() then
            return
        end
        if self.iconAdapter then
            self:_refreshOwnedIcon("waterfall_gift_asset_ready")
            return
        end
        if not useV2 then
            self:_addLegacyIconIfNotExist()
            return
        end

        local adapter, createError, cleanupOwner, provider, safeLegacy = self:createPackageIconAdapter()
        if not adapter then
            if cleanupOwner then
                self.iconAdapter = cleanupOwner
                self._iconAdapterCleanupPending = true
            elseif safeLegacy then
                self:_addLegacyIconIfNotExist()
            else
                logIconV2Error("create failed: " .. tostring(createError))
            end
            return
        end

        self.iconAdapter = adapter
        self.iconDataProvider = provider
        self._iconAdapterCleanupPending = false
        self.icon = adapter:getIcon()
        if self:isV2IconActive() then
            self:dcQualify()
            local scheduled, scheduleError = self:_scheduleIconV2Boundary()
            if scheduled == false then
                logIconV2Error("schedule boundary after create failed: " .. tostring(scheduleError))
            end
        else
            IconEventCenter:refreshIconEvent(IconKey.kWaterfallGift)
        end
    end)
end

function WaterfallGiftManager:updateIcon()
    if dataModel and dataModel:isActValid() and self.giftModule:hasGifts() then
        if self._iconAdapterCleanupPending then
            local cleaned = self:_disposeIconAdapter()
            if cleaned == false then
                return false
            end
        end
        if self.iconAdapter then
            self.icon = self.iconAdapter:getIcon()
            return self:_refreshOwnedIcon("waterfall_gift_update")
        end
        self.icon = _G.amfBean("IconManager"):getIconByIconKey(IconKey.kWaterfallGift)
        if not self.icon then
            self:doCreateIconAsync()
        end
        self:_refreshOwnedIcon("waterfall_gift_update")
    else
        return self:onDeprecated()
    end
    return true
end

