function WaterfallGiftManager:onDeprecated()
    self:_cancelIconV2BoundaryTimer()
    if self.iconAdapter then
        return self:_disposeIconAdapter()
    end
    IconEventCenter:removeIconEvent(IconKey.kWaterfallGift)
    self.icon = nil
