function WaterfallGiftManager:requestFreeNodeReward(rewardIndex, onSuccess, onFail, onCancel)
    dataModel:requestFreeNodeReward(rewardIndex):next(function(response)
        local data = response:getData() or {}
        local rewards = data.rewards or {}
        local extraMap = {}

        local realFreeNum = dataModel:getRealFreeNum()
        if rewardIndex <= realFreeNum then
            extraMap = { pay_type = DcPayType.kFree }
        else
            extraMap = { pay_type = DcPayType.kRmb }
        end
        self:addRewards(rewards, "sprog_icebreaking", "get_reward", extraMap)
        safeRunCall(onSuccess, rewards)
    end, function(response)
        if response:isCancel() then
            safeRunCall(onCancel)
        else
            local errCode = response:getErrorCode()
            if errCode then
                CommonTip:showTip(localize("error.tip."..tostring(errCode)))
            end
            safeRunCall(onFail)
        end
    end)
end

