function WaterfallGiftManager:addRewards(rewards, dcFeature, dcSource, extraMap)
    if extraMap == nil then extraMap = {} end
    if not dcFeature or not dcSource then
        dcFeature, dcSource = self:getFeatureAndSource()
    end

    _G.GainPropData:create()
    :setFeature(dcFeature)
    :setSource(dcSource)
    :setProps(rewards)
    :setExtraMap(extraMap)
    :execute()
end

