--------------------------强弹相关--------------------------
function WaterfallGiftManager:checkNeedAutoPopout(sceneType)
    if not self:isEnabled() then return false end
    local config = dataModel:getAutoPopoutConfig()

    -- 强弹时间
    local autoPopoutCd = config.autoPopoutCd
    local lastPopTime = dataModel:getLastPopoutTime()
    if (TimeKit:timeInSec()-lastPopTime) < autoPopoutCd*3600 then
        log("checkNeedAutoPopout time in cd", TimeKit:timeInSec(), lastPopTime, autoPopoutCd)
        return false
    end

    -- 条件
    local conditionList = config.conditionList
    if TimeKit:timeInSec() < 1769356740 then
        table.insertIfNotExist(conditionList, 3) --强行加场景2，因为配置没配，已触发活动的玩家无法更新配置
    end
    local AutoPopDefinition = Meta.AutoPopDefinition
    local conditionMetaList = config.conditionMetaList
    log("checkNeedAutoPopout condition check", tts(conditionList), sceneType)
    for i, conditionId in ipairs(conditionList) do
        local conditionMeta = conditionMetaList[conditionId] or {}
        local sceneId = conditionMeta.sceneId
        if sceneId == sceneType then
            local value = conditionMeta.conditionValue or 0
            local id = conditionMeta.conditionId
            if AutoPopDefinition[id] then
                local checkFunc = AutoPopDefinition[id]
                local res = checkFunc(value)
                if res ~= false then
                    log("checkNeedAutoPopout condition check pass", res)
                    return res
                end
            end
        end
    end
    return false
end

function WaterfallGiftManager:onActEnterMainScene(evt)
    if not self:isEnabled() then return end
    local param = evt:getData()
    if param.firstEnter then
        self.__enterMainSceneTime = TimeKit:timeInMillis()
    end
end

function WaterfallGiftManager:onGiftAutoSyncEnd()
    if dataModel and dataModel:isActValid() and self.giftModule:hasGifts() then
        if not self.__enterMainSceneTime or (TimeKit:timeInMillis() - self.__enterMainSceneTime < 3000) then
            local scene = Director:sharedDirector():getRunningSceneLua()
            if not scene or not scene:isScene("MainScene") then return end
            --场景2强弹
            local checkRes = self:checkNeedAutoPopout(2)
            if checkRes then
                local function onHandleOver()
                    AutoPopEventCenter:dispatch(AutoPopEvent.SINGLE_POP_OVER, PopupCheckPoint.WATERFALL_GIFT)
                end
                local creator = function ( ... )
                    log("stage2popup")
                    self:doAutoPopout(checkRes, onHandleOver)
                end

                local autoPopupMgr = _G.amfBean("AutoPopupMgr")
                autoPopupMgr:addPopupConfig(PopupCheckPoint.WATERFALL_GIFT, creator)
                if not autoPopupMgr:isRunnning() then
                    -- he_log_error("QaQ_waterfall_autopop_stage2_compensate")
                    autoPopupMgr:triggerStage2AutoPopup()
                end
            end
        end
    end
end

function WaterfallGiftManager:onActEnterStage3()
    if not self:isEnabled() then return end
    --场景3强弹
    local checkRes = self:checkNeedAutoPopout(3)
    if checkRes then
        local function onHandleOver()
            AutoPopEventCenter:dispatch(AutoPopEvent.SINGLE_POP_OVER, PopupCheckPoint.WATERFALL_GIFT)
        end
        local creator = function ( ... )
            log("stage3popup")
            self:doAutoPopout(checkRes, onHandleOver)
        end
        _G.amfBean("AutoPopupMgr"):addPopupConfig(PopupCheckPoint.WATERFALL_GIFT, creator)
    end
end

function WaterfallGiftManager:onActEnterStage4()
    if not self:isEnabled() then return end
    --场景4强弹
    local checkRes = self:checkNeedAutoPopout(4)
    if checkRes then
        local function onHandleOver()
            AutoPopEventCenter:dispatch(AutoPopEvent.SINGLE_POP_OVER, PopupCheckPoint.WATERFALL_GIFT)
        end
        local creator = function ( ... )
            log("stage4popup")
            self:doAutoPopout(checkRes, onHandleOver)
        end
        _G.amfBean("AutoPopupMgr"):addPopupConfig(PopupCheckPoint.WATERFALL_GIFT, creator)
    else
        self:popDyOfferTipPanel()
    end
end

function WaterfallGiftManager:doAutoPopout(autoPopType, callback)
    self.giftModule:pullOnce(2):next(function()
        local param = {
            panelSource = autoPopType,
            userClick = false,
            closeCallBack = callback
        }
        self:openGiftPanel(param)
        dataModel:setLastPopoutTime()
        if self:isV2IconActive() then
            self:_refreshOwnedIcon("waterfall_gift_auto_pop_shown")
        end
    end, function(errorCode)
        safeRunCall(callback)
    end)
end

-- 设置引导标记
function WaterfallGiftManager:addGuideIndex(index)
    if self:hasGuideIndex(index) then return end
    local guideIdSet = dataModel:getValue("userData.finishedGuideIds") or {}
    table.insert(guideIdSet, index)
    dataModel:setValue("userData.finishedGuideIds", guideIdSet)
    -- 引导标记
    local SetActGuidFlag = require "amf.middleware.activity.http.SetActGuidFlag"
    SetActGuidFlag:post({
        actId = ACT_ID,
        index = index
    })
end

function WaterfallGiftManager:hasGuideIndex(index)
    local guideIdSet = dataModel:getValue("userData.finishedGuideIds") or {}
    return table.exist(guideIdSet, index)
end

