function WaterfallGiftManager:getIconShowTipText(lowEnergy)
    if self:isDouyinMarketing() then
        if self:isDouyinRandomMarketing() then
            return self:getDyRandomModeIconTipText()
        end
        return "抖音支付最高减20元"
    end
    local tipList = Meta.IconTipText
    if tipList then
        return tipList[lowEnergy and 2 or 1]
    end
end

function WaterfallGiftManager:checkIconTip(config)
    if not self:isEnabled() then return end
    local lowEnergy = Meta.checkRemainEnergy(nil, 5)

    local IconTipEventCenter = require("amf.feature.icontip.event.IconTipEventCenter")
    IconTipEventCenter:dispatch(IconTipEvent.ADD_ICON_TIP, {
        iconKey = IconKey.kWaterfallGift,
        iconType = IconTipType.MESSAGE,
        typeIndex = 1,
        creatorDelegate = {
            tipsType = HomeIconTipsType.ONLY_TEXT,
            text = self:getIconShowTipText(lowEnergy),
        },
        popFunc = function()
        end,
        config = config
    })
end
