---抖音瀑布流营销开关
function WaterfallGiftManager:isDouyinMarketing()
    if EnvUtil:isWindows() then return true end
    if not EnvUtil:isAndroid() then return end
    if not dataModel or not dataModel:isInDyPayMarketing() then return end

    local paymentManager = _G.amfBean("PaymentManager")
    local validTypes = paymentManager:getValidPayTypes()
    if table.exist(validTypes, Payments.DOUYIN_ANDROID) then
        return true
    end
end

function WaterfallGiftManager:isDouyinRandomMarketing()
    return dataModel and dataModel:isDouyinRandomMarketing()
end

