end

function WaterfallGiftManager:findThenQueryDyOffer()
    local deferred = require "amf.script.sugar.deferred"
    local d = deferred.new()
    local userData = self:getUserData() or {}
    local actConfig = self:getActConfig() or {}
    local fixedGiftCfg = actConfig.fixRewardNodeList
    local curIdx = userData.gotRewardNodeIndex
    local needQuery = false
    for i = 1, 6 do
        local cfg = fixedGiftCfg[curIdx + i]
        if cfg then
            if not cfg.freeNode and cfg.goodsId then
                local goodsObj = GoodsManager:getGoods(cfg.goodsId)
                if goodsObj then
                    local price = goodsObj:getPrice()
                    self:queryDyOffer(price, d)
                    needQuery = true
                    break
                end
            end
        else
            break
        end
    end
    if not needQuery then
        d:reject()
    end
    return d
end

function WaterfallGiftManager:queryDyOffer(price, d)
    local Req = require "amf.middleware.purchase.http.DouyinTiktokPrepayConsult"
    local req = Req:post({
        price = price,
        goodsTagActKey = "waterfall2025",
    })
    if not req then
        d:reject()
        return
    end

    req:next(function(response)
        local data = response:getData()
        if not data or not data.viewData or not data.viewData.operationTip then
            d:reject()
            return
        end

        local offerInfo = {
            price = price,
            operationTip = data.viewData.operationTip,
            assignDiscountKey = data.assignDiscountKey,
            goodsTag = data.goodsTag,
        }

        if data.goodsTag then
            local tags = table.deserialize(data.goodsTag)
            if tags and tags.dyType then
                offerInfo.dyType = tags.dyType
            end
        end

        local discount
        if data.viewData.operationMinAmount then
            if data.viewData.operationMinAmount == data.viewData.operationMaxAmount then
                discount = tonumber(data.viewData.operationMinAmount)
            end
        else
            discount = tonumber(string.match(data.viewData.operationTip, "^立减(%d+%.?%d*)元$"))
        end

        if discount then
            offerInfo.discount = discount
            offerInfo.finalPrice = (price * 1000 - discount * 1000) / 1000
        end
        d:resolve(offerInfo)
    end, function()
        d:reject()
    end)
end

function WaterfallGiftManager:showDyOfferTipPanel(dyOfferInfo, nextCallback)
    if not dyOfferInfo then
        if nextCallback then nextCallback() end
        return
    end

    local WaterfallMarketingPanelVM = force_require "amf.feature.localactivity.waterfallgift.view.WaterfallMarketingPanelVM"
    local vm = WaterfallMarketingPanelVM:create({
        dyOfferInfo = dyOfferInfo,
        nextCallback = nextCallback,
    })
    vm:popout()

    self:dc("sprog_icebreaking", "douyin_guide_show")
end

function WaterfallGiftManager:onPaySuccess(payType)
    if not self:isDouyinMarketing() then return end

    if payType == Payments.DOUYIN_ANDROID then
        if not self:hasGuideIndex(Meta.DyOfferGuideId.PAY_END_4) then
            for i = 1, 4 do
                local checkGuideIdx = Meta.DyOfferGuideId.PAY_END_1 + i - 1
                if not self:hasGuideIndex(checkGuideIdx) then
                    self:addGuideIndex(checkGuideIdx)
                    break
                end
            end
        end
    end
end

function WaterfallGiftManager:popDyOfferTipPanel()
    if not self:isDouyinMarketing() then return end

    local canPop = not self:hasGuideIndex(Meta.DyOfferGuideId.PAY_END_4)
    if canPop then
        local queryPromise = self:findThenQueryDyOffer()

        local function onHandleOver()
            AutoPopEventCenter:dispatch(AutoPopEvent.SINGLE_POP_OVER, PopupCheckPoint.WATERFALL_GIFT_DY_OFFER)
        end

        local creator = function ()
            log("stage4popup")
            queryPromise:next(function(dyOfferInfo)
                self:showDyOfferTipPanel(dyOfferInfo, onHandleOver)
            end, onHandleOver)

            setTimeOut(function()
                queryPromise:reject()
            end, 1.5)
        end
        _G.amfBean("AutoPopupMgr"):addPopupConfig(PopupCheckPoint.WATERFALL_GIFT_DY_OFFER, creator)
    end
end

--endregion

return WaterfallGiftManager
